/// State machine for GoalState workflow
#[derive(Debug, Clone)]
pub struct GoalStateStateMachine {
    current_state: GoalStateState,
}

impl GoalStateStateMachine {
    /// Create a new state machine with initial state
    pub fn new() -> Self {
        Self {
            current_state: GoalStateState::default(),
        }
    }

    /// Create from an existing state
    pub fn from_state(state: GoalStateState) -> Self {
        Self { current_state: state }
    }

    /// Get the current state
    pub fn current_state(&self) -> GoalStateState {
        self.current_state
    }

    /// Check if a transition is allowed from the current state
    pub fn can_transition(&self, transition: GoalStateTransition) -> bool {
        if matches!(self.current_state, GoalStateState::Failed | GoalStateState::Canceled) {
            return false;
        }

        match (self.current_state, transition) {
            (GoalStateState::Draft, GoalStateTransition::Start) => true,
            (GoalStateState::Inprogress, GoalStateTransition::EvaluateMet) => true,
            (GoalStateState::Inprogress, GoalStateTransition::ManualReach) => true,
            (GoalStateState::Inprogress, GoalStateTransition::WindowClose) => true,
            (GoalStateState::Draft, GoalStateTransition::Cancel) => true,
            (GoalStateState::Inprogress, GoalStateTransition::Cancel) => true,
            (GoalStateState::Reached, GoalStateTransition::Cancel) => true,
            _ => false,
        }
    }

    /// Check if a transition is allowed for a given role
    pub fn can_transition_with_role(&self, transition: GoalStateTransition, role: &str) -> bool {
        if !self.can_transition(transition) {
            return false;
        }

        let allowed_roles = transition.allowed_roles();
        if allowed_roles.is_empty() {
            return true; // No role restriction
        }

        allowed_roles.iter().any(|r| *r == role || *r == "*")
    }

    /// Apply a transition, returning the new state
    pub fn transition(&mut self, transition: GoalStateTransition) -> Result<GoalStateState, StateMachineError> {
        if !self.can_transition(transition) {
            return Err(StateMachineError::TransitionNotAllowed {
                transition: transition.to_string(),
                from: self.current_state.to_string(),
            });
        }

        self.current_state = transition.target_state();
        Ok(self.current_state)
    }

    /// Apply a transition with role check
    pub fn transition_with_role(&mut self, transition: GoalStateTransition, role: &str) -> Result<GoalStateState, StateMachineError> {
        // Check basic transition validity first
        if !self.can_transition(transition) {
            return Err(StateMachineError::TransitionNotAllowed {
                transition: transition.to_string(),
                from: self.current_state.to_string(),
            });
        }

        // Check role authorization
        if !self.can_transition_with_role(transition, role) {
            return Err(StateMachineError::RoleNotAuthorized {
                role: role.to_string(),
                transition: transition.to_string(),
            });
        }

        self.current_state = transition.target_state();
        Ok(self.current_state)
    }

    /// Get all available transitions from the current state
    pub fn available_transitions(&self) -> Vec<GoalStateTransition> {
        GoalStateTransition::all()
            .into_iter()
            .filter(|t| self.can_transition(*t))
            .collect()
    }

    /// Get all available transitions for a given role
    pub fn available_transitions_for_role(&self, role: &str) -> Vec<GoalStateTransition> {
        GoalStateTransition::all()
            .into_iter()
            .filter(|t| self.can_transition_with_role(*t, role))
            .collect()
    }

    /// Attempt to transition directly to a target state.
    ///
    /// Finds any transition that leads to the target state and applies it.
    /// Returns Err if no valid transition leads from current state to target.
    pub fn transition_to_state(&mut self, target: GoalStateState) -> Result<GoalStateState, StateMachineError> {
        let valid = GoalStateTransition::all().into_iter()
            .filter(|t| self.can_transition(*t))
            .find(|t| t.target_state() == target);
        match valid {
            Some(t) => self.transition(t),
            None => Err(StateMachineError::TransitionNotAllowed {
                transition: target.to_string(),
                from: self.current_state.to_string(),
            }),
        }
    }
}

